"""High-resolution embedded badge assets and tier styling for GitHub Achievements.

Adheres to Single Responsibility Principle (SRP): provides base64 image data URIs
and metallic tier border / badge styling for SVG card rendering.
"""

import urllib.parse
from typing import Optional

# Base64-encoded 80x80 crisp PNGs of official GitHub achievements
ACHIEVEMENT_BADGE_DATA_URIS = {
    "pull-shark": "data:image/png;base64,",
    "starstruck": "data:image/png;base64,",
    "galaxy-brain": "data:image/png;base64,",
    "pair-extraordinaire": "data:image/png;base64,",
    "quickdraw": "data:image/png;base64,",
    "yolo": "data:image/png;base64,",
    "public-sponsor": "data:image/png;base64,",
}


TIER_COLORS = {
    "gold": {
        "border": "#e3b341",
        "bg": "#2f2409",
        "badge_bg": "#d29922",
        "text": "#f0b72f",
        "glow": "rgba(227, 179, 65, 0.4)",
    },
    "silver": {
        "border": "#8b949e",
        "bg": "#161b22",
        "badge_bg": "#6e7681",
        "text": "#c9d1d9",
        "glow": "rgba(139, 148, 158, 0.35)",
    },
    "bronze": {
        "border": "#bf8600",
        "bg": "#281a0e",
        "badge_bg": "#9e6a03",
        "text": "#d4883b",
        "glow": "rgba(191, 134, 0, 0.35)",
    },
    "default": {
        "border": "#388bfd",
        "bg": "#0d1117",
        "badge_bg": "#1f6feb",
        "text": "#58a6ff",
        "glow": "rgba(56, 139, 253, 0.3)",
    },
    "locked": {
        "border": "#30363d",
        "bg": "#161b22",
        "badge_bg": "#21262d",
        "text": "#6e7681",
        "glow": "none",
    },
}


def get_tier_style(tier: str) -> dict[str, str]:
    """Return color tokens and styling for a given tier."""
    return TIER_COLORS.get(tier.lower(), TIER_COLORS["default"])


def get_achievement_badge_data_uri(achievement_id: str) -> str:
    """Return base64 data URI for an achievement icon, or fallback SVG data URI."""
    clean_id = achievement_id.lower().replace("_", "-")
    if clean_id in ACHIEVEMENT_BADGE_DATA_URIS:
        return ACHIEVEMENT_BADGE_DATA_URIS[clean_id]

    # Dynamic fallback vector badge
    abbr = clean_id[:3].upper()
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">'
        f'<circle cx="40" cy="40" r="38" fill="#161b22" stroke="#58a6ff" stroke-width="3"/>'
        f'<text x="40" y="46" text-anchor="middle" fill="#f0f6fc" '
        f'font-size="18" font-weight="bold" font-family="sans-serif">{abbr}</text>'
        f'</svg>'
    )
    return f'data:image/svg+xml,{urllib.parse.quote(svg)}'
